import React from 'react';

function ScoreCircle({ score, size = 120 }) {
  const getColor = (s) => {
    if (s >= 80) return '#2ed573';
    if (s >= 60) return '#ffa502';
    if (s >= 40) return '#ff6b35';
    return '#ff4757';
  };

  const getRisk = (s) => {
    if (s >= 90) return 'SAFE';
    if (s >= 70) return 'LOW RISK';
    if (s >= 50) return 'MEDIUM';
    if (s >= 30) return 'HIGH RISK';
    return 'CRITICAL';
  };

  const color = getColor(score);

  return (
    <div
      className="score-circle"
      style={{
        width: size,
        height: size,
        borderColor: color,
        boxShadow: `0 0 20px ${color}33`,
      }}
    >
      <span className="score-num" style={{ color }}>{score}</span>
      <span className="score-label" style={{ color }}>{getRisk(score)}</span>
    </div>
  );
}

export default ScoreCircle;
