// Frontend vulnerability detector (no backend needed)
const rules = [
  {
    name: 'SQL Injection',
    severity: 'High',
    patterns: [
      /query\s*\(\s*[`"'].*\$\{/i,
      /query\s*\(\s*["'`].*\+\s*(req\.|user|input)/i,
      /execute\s*\(\s*["'`].*SELECT.*\+/i,
      /db\.query\s*\(\s*`[^`]*\$\{/i,
      /"SELECT.*"\s*\+/i,
    ],
    description: 'User input is directly concatenated into SQL queries without sanitization.',
    impact: 'Attackers can manipulate queries to read, modify, or delete database data.',
    recommendation: 'Use parameterized queries or prepared statements instead of string concatenation.',
    secureExample: `// Insecure:\ndb.query("SELECT * FROM users WHERE id = " + userId);\n\n// Secure:\ndb.query("SELECT * FROM users WHERE id = ?", [userId]);`,
  },
  {
    name: 'Cross-Site Scripting (XSS)',
    severity: 'High',
    patterns: [
      /innerHTML\s*=\s*(req\.|user|input|params|query)/i,
      /document\.write\s*\(/i,
      /res\.send\s*\(\s*req\.(body|query|params)/i,
      /innerHTML\s*=\s*`[^`]*\$\{/i,
      /\.html\s*\(\s*userInput/i,
    ],
    description: 'Unescaped user input is rendered directly into the HTML of a page.',
    impact: 'Attackers can inject malicious scripts that steal cookies, session tokens, or redirect users.',
    recommendation: 'Always sanitize and escape user input. Use DOMPurify or textContent instead of innerHTML.',
    secureExample: `// Insecure:\nelement.innerHTML = userInput;\n\n// Secure:\nelement.textContent = userInput;\n// Or:\nelement.innerHTML = DOMPurify.sanitize(userInput);`,
  },
  {
    name: 'Hardcoded Password',
    severity: 'High',
    patterns: [
      /password\s*=\s*["'][^"']{4,}["']/i,
      /passwd\s*=\s*["'][^"']{4,}["']/i,
      /secret\s*=\s*["'][^"']{4,}["']/i,
      /api_?key\s*=\s*["'][^"']{8,}["']/i,
      /token\s*=\s*["'][A-Za-z0-9+/]{20,}["']/,
    ],
    description: 'Credentials or secrets are hardcoded directly in the source code.',
    impact: 'Anyone with codebase access can extract credentials. Secrets in version control cannot be easily revoked.',
    recommendation: 'Store secrets in environment variables (.env files). Never commit secrets to version control.',
    secureExample: `// Insecure:\nconst password = "admin123";\n\n// Secure:\nconst password = process.env.DB_PASSWORD;`,
  },
  {
    name: 'Sensitive Data Exposure',
    severity: 'Medium',
    patterns: [
      /console\.log\s*\(.*password/i,
      /console\.log\s*\(.*token/i,
      /console\.log\s*\(.*secret/i,
      /res\.json\s*\(\s*\{.*password/i,
      /res\.send\s*\(.*password/i,
    ],
    description: 'Sensitive data such as passwords or tokens are logged or sent in API responses.',
    impact: 'Sensitive info can be exposed in server logs, browser consoles, or API responses.',
    recommendation: 'Never log sensitive data. Remove password fields from API responses.',
    secureExample: `// Insecure:\nconsole.log("User:", user.password);\n\n// Secure:\nconst { password, ...safeUser } = user;\nres.json(safeUser);`,
  },
  {
    name: 'Command Injection',
    severity: 'High',
    patterns: [
      /exec\s*\(\s*[`"'].*\$\{/i,
      /exec\s*\(\s*["'`].*\+\s*(req\.|user|input)/i,
      /execSync\s*\(\s*[`"'].*\$\{/i,
      /child_process.*exec.*req\./i,
      /shell\s*:\s*true/i,
    ],
    description: 'User input is passed directly to system command execution functions.',
    impact: 'Attackers can execute arbitrary system commands, potentially gaining full server control.',
    recommendation: 'Never pass user input to exec/execSync. Validate and whitelist inputs strictly.',
    secureExample: `// Insecure:\nexec('ls ' + req.query.dir);\n\n// Secure:\nconst safePath = path.basename(req.query.dir);\nfs.readdir(safePath, callback);`,
  },
  {
    name: 'Insecure File Handling',
    severity: 'Medium',
    patterns: [
      /readFile\s*\(\s*req\.(body|query|params)/i,
      /readFileSync\s*\(\s*req\.(body|query|params)/i,
      /path\.join\s*\(.*req\.(body|query|params)/i,
      /fs\.(read|write).*req\./i,
    ],
    description: 'User-controlled input is used directly in file system operations without validation.',
    impact: 'Attackers can use path traversal (../../etc/passwd) to read or write arbitrary files.',
    recommendation: 'Validate file paths. Use path.basename() to strip directory traversal attempts.',
    secureExample: `// Insecure:\nfs.readFile(req.query.filename, cb);\n\n// Secure:\nconst safe = path.basename(req.query.filename);\nfs.readFile(path.join(__dirname, 'uploads', safe), cb);`,
  },
  {
    name: 'Weak Authentication',
    severity: 'Medium',
    patterns: [
      /createHash\s*\(\s*["']md5["']\s*\)/i,
      /createHash\s*\(\s*["']sha1["']\s*\)/i,
      /md5\s*\(/i,
      /jwt\.sign\s*\(.*algorithm.*none/i,
    ],
    description: 'Weak or outdated hashing algorithms (MD5, SHA1) are used for passwords.',
    impact: 'Passwords hashed with weak algorithms can be cracked quickly using rainbow tables.',
    recommendation: 'Use bcrypt, argon2, or scrypt for password hashing. Use HS256+ for JWT.',
    secureExample: `// Insecure:\nconst hash = md5(password);\n\n// Secure:\nconst bcrypt = require('bcrypt');\nconst hash = await bcrypt.hash(password, 12);`,
  },
  {
    name: 'Debug Information Leakage',
    severity: 'Low',
    patterns: [
      /res\.send\s*\(\s*err\.stack/i,
      /res\.json\s*\(\s*err\s*\)/i,
      /res\.json\s*\(\s*\{[^}]*stack/i,
      /app\.use\s*\(\s*function\s*\(\s*err/i,
    ],
    description: 'Internal error details or stack traces are exposed to the client.',
    impact: 'Attackers gain insight into server internals, file paths, and application structure.',
    recommendation: 'Return generic error messages to clients. Log details server-side only.',
    secureExample: `// Insecure:\nres.json({ error: err.stack });\n\n// Secure:\nconsole.error(err);\nres.status(500).json({ message: "Internal server error" });`,
  },
];

export function analyzeCode(code) {
  const findings = [];
  const lines = code.split('\n');

  for (const rule of rules) {
    for (const pattern of rule.patterns) {
      let matched = false;
      let lineNumber = null;

      lines.forEach((line, idx) => {
        if (!matched && pattern.test(line)) {
          matched = true;
          lineNumber = idx + 1;
        }
      });

      if (matched && !findings.find((f) => f.name === rule.name)) {
        findings.push({ ...rule, lineNumber, patterns: undefined });
        break;
      }
    }
  }

  let score = 100;
  findings.forEach((f) => {
    if (f.severity === 'High') score -= 20;
    else if (f.severity === 'Medium') score -= 10;
    else score -= 5;
  });
  score = Math.max(0, score);

  const getRisk = (s) => {
    if (s >= 90) return 'Safe';
    if (s >= 70) return 'Low';
    if (s >= 50) return 'Medium';
    if (s >= 30) return 'High';
    return 'Critical';
  };

  return {
    findings,
    securityScore: score,
    riskLevel: getRisk(score),
    totalVulnerabilities: findings.length,
    highCount: findings.filter((f) => f.severity === 'High').length,
    mediumCount: findings.filter((f) => f.severity === 'Medium').length,
    lowCount: findings.filter((f) => f.severity === 'Low').length,
  };
}

export const SAMPLE_VULNERABLE_CODE = `// ⚠️ This code contains intentional security vulnerabilities for demo purposes

const express = require('express');
const mysql = require('mysql');
const { exec } = require('child_process');
const fs = require('fs');
const md5 = require('md5');
const app = express();

const db = mysql.createConnection({ host: 'localhost', user: 'root', password: 'admin123' });

// SQL Injection vulnerability
app.get('/user', (req, res) => {
  const userId = req.query.id;
  db.query("SELECT * FROM users WHERE id = " + userId, (err, result) => {
    res.json(result);
  });
});

// XSS vulnerability
app.get('/greet', (req, res) => {
  res.send('<h1>Hello ' + req.query.name + '</h1>');
});

// Command Injection vulnerability
app.get('/ping', (req, res) => {
  exec('ping ' + req.query.host, (err, stdout) => {
    res.send(stdout);
  });
});

// Weak hashing
app.post('/login', (req, res) => {
  const hash = md5(req.body.password);
  console.log("User password:", req.body.password);
});

// Insecure file read
app.get('/file', (req, res) => {
  fs.readFile(req.query.filename, 'utf8', (err, data) => {
    res.send(data);
  });
});
`;
